#[test]
fn rev_matches_the_golden_files() {
    for (name, want) in GOLDEN_REVS {
        let (p, marshal) = golden(name);
        assert_eq!(
            canonical_json(&p),
            marshal.trim_end(),
            "{name}: canonical JSON"
        );
        assert_eq!(rev(&p), *want, "{name}");
    }
}

